// Dia a calcular (AAAA-MM-DD, horário de Brasília). Pelo app: o dia pedido; pela agenda: hoje.
const hojeBR = new Date(Date.now() - 3 * 3600e3).toISOString().slice(0, 10);
let corpo = null;
try { if ($('Recebe pedido do app').isExecuted) corpo = $('Recebe pedido do app').first().json.body || {}; } catch (e) { corpo = null; }
if (!corpo) return [{ json: { dia: hojeBR, origem: 'agenda', erro: '' } }];
const dia = String(corpo.dia || '').trim() || hojeBR;
const ok = /^\d{4}-\d{2}-\d{2}$/.test(dia) && !isNaN(new Date(dia + 'T12:00:00Z')) && new Date(dia + 'T12:00:00Z').toISOString().slice(0, 10) === dia;
return [{ json: { dia, origem: 'app', erro: ok ? '' : 'Dia inválido.' } }];

const dia = $('Define o dia').first().json.dia;
// Base da empresa (Rua Canelinha, 68, Joinville), já consultada no mapa.
const BASE_GEO = { lat: -26.3201511, lon: -48.8750111 };
const UA = { 'User-Agent': 'solucoes-rapidas-sistema/1.0 (uso interno)' };
const URL_BANCO = 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B';
const espera = (ms) => new Promise((ok) => setTimeout(ok, ms));
const todos = (nome) => $(nome).all().map((i) => i.json).filter((j) => j && j.id && j.fields);
const primeiro = (v) => (Array.isArray(v) ? v[0] : v) || '';
const num = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v));
const r2 = (n) => Math.round(n * 100) / 100;
const normal = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();

const visitas = todos('Busca visitas');
const chamados = new Map(todos('Busca chamados').map((c) => [c.id, c]));
const locais = todos('Busca locais');
const veiculo = todos('Busca veículo')[0] || { fields: {} };
const pneus = todos('Busca pneus');
const geoGuardado = new Map(todos('Busca endereços').map((g) => [g.fields.Endereco, g.fields]));

// Visitas iniciadas no dia (horário de Brasília), na ordem em que começaram.
const diaBR = (iso) => new Date(new Date(iso).getTime() - 3 * 3600e3).toISOString().slice(0, 10);
const doDia = visitas.filter((v) => v.fields.Inicio_Real && diaBR(v.fields.Inicio_Real) === dia)
  .sort((a, b) => new Date(a.fields.Inicio_Real) - new Date(b.fields.Inicio_Real));

// Endereço de cada visita: o do chamado; cidade/UF pelo local do cliente com o mesmo endereço.
function enderecoDa(v) {
  const ch = chamados.get(primeiro(v.fields.Chamado));
  if (!ch) return null;
  const end = String(ch.fields.Endereco_Copia || '').trim();
  if (!end) return null;
  const cliente = primeiro(ch.fields.Cliente_Ref);
  const doCliente = locais.filter((l) => !cliente || [].concat(l.fields.Cliente_Vinculado || []).includes(cliente));
  const igual = doCliente.find((l) => normal(l.fields.Endereco_Completo) === normal(end))
    || locais.find((l) => normal(l.fields.Endereco_Completo) === normal(end));
  const bc = String((igual && igual.fields.Bairro_Cidade) || '');
  // "Bairro / Cidade - UF"
  const m = /\/\s*([^/]+?)\s*-\s*([A-Za-z]{2})\s*$/.exec(bc);
  const cidade = m ? m[1].trim() : 'Joinville';
  const uf = m ? m[2].toUpperCase() : 'SC';
  const cep = (/(\d{5})-?(\d{3})/.exec(end) || []).slice(1).join('-');
  const semCep = end.replace(/,?\s*CEP\s*\d{5}-?\d{3}/i, '').replace(/\d{5}-\d{3}/, '').trim().replace(/,\s*$/, '');
  const partes = semCep.split(',').map((p) => p.trim()).filter(Boolean);
  const rua = partes[0] || '';
  const numero = (partes.slice(1).find((p) => /^\d+[A-Za-z]?$/.test(p)) || '');
  return { chave: normal(end + ' | ' + cidade + ' - ' + uf), rua, numero, cidade, uf, cep };
}

// Coordenadas: do que já está guardado; senão pergunta ao mapa (1 por segundo, regra do serviço).
const novosGeo = [];
let consultasMapa = 0;
async function coordenadas(e) {
  if (geoGuardado.has(e.chave)) {
    const g = geoGuardado.get(e.chave);
    return g.Achou ? { lat: Number(g.Lat), lon: Number(g.Lon) } : null;
  }
  const tentativas = [
    e.numero ? `${e.rua}, ${e.numero}, ${e.cidade}, ${e.uf}, Brasil` : null,
    `${e.rua}, ${e.cidade}, ${e.uf}, Brasil`,
  ].filter(Boolean);
  let achado = null, consulta = '';
  for (const q of tentativas) {
    if (consultasMapa) await espera(1100);
    consultasMapa++;
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://nominatim.openstreetmap.org/search', qs: { format: 'json', limit: 1, countrycodes: 'br', q }, headers: UA, json: true, timeout: 20000 });
      if (Array.isArray(r) && r[0]) { achado = { lat: Number(r[0].lat), lon: Number(r[0].lon) }; consulta = q; break; }
    } catch (err) { /* serviço fora: tenta a próxima forma; se nada der, fica sem km */ }
    consulta = q;
  }
  const g = { Endereco: e.chave, Consulta: consulta, Lat: achado ? achado.lat : null, Lon: achado ? achado.lon : null, Achou: Boolean(achado) };
  geoGuardado.set(e.chave, g);
  novosGeo.push(g);
  return achado;
}

const pontos = [];
const semEndereco = [];
const naoAchados = [];
for (const v of doDia) {
  const e = enderecoDa(v);
  if (!e) { semEndereco.push(v.id); continue; }
  const c = await coordenadas.call(this, e);
  if (!c) { naoAchados.push(v.id); continue; }
  pontos.push({ visita: v, ...c });
}

// Rota base -> clientes -> base, numa consulta só.
let trechos = null;
let erroRota = '';
if (pontos.length) {
  const coords = [BASE_GEO, ...pontos, BASE_GEO].map((p) => p.lon.toFixed(6) + ',' + p.lat.toFixed(6)).join(';');
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://router.project-osrm.org/route/v1/driving/' + coords, qs: { overview: 'false' }, headers: UA, json: true, timeout: 30000 });
    if (r && r.code === 'Ok' && r.routes && r.routes[0]) trechos = r.routes[0].legs.map((l) => l.distance / 1000);
    else erroRota = 'A rota não foi encontrada.';
  } catch (err) { erroRota = 'O serviço de rotas não respondeu.'; }
}

// Custo do km, por partes (outras partes entram aqui no futuro).
const vf = veiculo.fields || {};
const consumo = num(vf.Consumo_Km_L);
const precoLitro = num(vf.Preco_Litro);
const desgastes = pneus.filter((p) => p.fields.Posicao !== 'Estepe').map((p) => num(p.fields.Desgaste_R_Km)).filter((n) => n !== null);
const porKm = {};
if (consumo && precoLitro) porKm.combustivel = precoLitro / consumo;
if (desgastes.length) porKm.pneus = desgastes.reduce((a, b) => a + b, 0);
const custoKm = Object.values(porKm).reduce((a, b) => a + b, 0);
const avisos = [];
if (!precoLitro) avisos.push('Sem preço do litro: o combustível ficou fora da conta.');
if (!consumo) avisos.push('Sem consumo (km/l): o combustível ficou fora da conta.');
if (erroRota) avisos.push(erroRota);
if (naoAchados.length) avisos.push(naoAchados.length + ' endereço(s) não achado(s) no mapa.');
if (semEndereco.length) avisos.push(semEndereco.length + ' atendimento(s) sem endereço.');

const agora = new Date().toISOString();
const mudancas = [];
let kmDia = 0, custoDia = 0;
if (trechos) {
  pontos.forEach((p, i) => {
    let km = trechos[i];
    const ultimo = i === pontos.length - 1;
    if (ultimo) km += trechos[i + 1];
    km = Math.round(km * 10) / 10;
    const partes = {};
    for (const [k, v] of Object.entries(porKm)) partes[k] = r2(km * v);
    const custo = custoKm > 0 ? r2(km * custoKm) : null;
    kmDia += km; if (custo) custoDia += custo;
    mudancas.push({ id: p.visita.id, fields: {
      Km_Deslocamento: km, Custo_Deslocamento: custo, Calculado_Em: agora,
      Custo_Detalhe: JSON.stringify({ versao: 1, dia, ordem: i + 1, de: i === 0 ? 'base' : 'atendimento anterior', voltaBase: ultimo,
        km, porKm: Object.fromEntries(Object.entries(porKm).map(([k, v]) => [k, Math.round(v * 10000) / 10000])), partes,
        precoLitro, consumo, pneusSomados: desgastes.length }),
    } });
  });
}
// Quem ficou sem km também é marcado, para o app mostrar o motivo.
for (const id of [...semEndereco, ...naoAchados]) {
  mudancas.push({ id, fields: { Km_Deslocamento: null, Custo_Deslocamento: null, Calculado_Em: agora,
    Custo_Detalhe: JSON.stringify({ versao: 1, dia, motivo: semEndereco.includes(id) ? 'sem endereço' : 'endereço não achado no mapa' }) } });
}

const resumo = { ok: true, dia, atendimentos: doDia.length, calculados: trechos ? pontos.length : 0,
  km: Math.round(kmDia * 10) / 10, custo: r2(custoDia), custoKm: Math.round(custoKm * 10000) / 10000, avisos };

const itens = [];
for (let i = 0; i < novosGeo.length; i += 10) itens.push({ metodo: 'POST', url: URL_BANCO + '/Geo_Enderecos', corpo: { records: novosGeo.slice(i, i + 10).map((fields) => ({ fields })) } });
for (let i = 0; i < mudancas.length; i += 10) itens.push({ metodo: 'PATCH', url: URL_BANCO + '/Visitas', corpo: { records: mudancas.slice(i, i + 10) } });
if (!itens.length) return [{ json: { pular: true, resumo } }];
return itens.map((j, i) => ({ json: { ...j, resumo: i === 0 ? resumo : undefined } }));
